sys_ux_client_script.script:
var ga = new GlideAjax('StudentLoginUtils');      // Script Include name
ga.addParam('sysparm_name', 'validateStudent');   // Function name
ga.addParam('sysparm_username', state.username);
ga.addParam('sysparm_password', state.password);

ga.getXMLAnswer(function(response){
    response = (response || '').trim();
    if(response.toLowerCase() === "success"){
        window.location.href = "/student-dashboard"; 
    } else {
        alert("Invalid Username or Password");
    }
});
